```php
 public function syncAltArchEvents(Request $request)
    {

        $sai = SkudArchIncrement::where(\'key_name\', \'skud_arch_daily\')->first();
        if ($sai == null){
            // STARTER KIT
            // Если нет строки в базе данных, создаём её и записываем айдишники событий, близких к концу дня (реально могут быть и как вчера и как завтра, так как порядок id не сответствует порядку дат)
            $sai = [\'key_name\' => \'skud_arch_daily\', \'arch_id\' => 0, \'add_arch_id\' => 0, \'updated_at\' => Carbon::now()];
            $item = ArchEvents::where(\'datetime_contr\', \'<\', Carbon::now()->startOf(\'day\'))
                ->orderBy(\'pkey\', \'DESC\')->first();
            // В массив сразу записываем актуальные айдишники последних событий
            $sai[\'arch_id\'] = $item->pkey;
            $item2 = SkudAddArchEvent::orderBy(\'id\', \'DESC\')->first();
            $sai[\'add_arch_id\'] = $item2->id;
            SkudArchIncrement::insert($sai);

        } else {
            $sai = $sai->toArray();
        };

        $last_sync_date = Carbon::parse($sai[\'updated_at\']);
        $current_date = $last_sync_date->clone();
        $now = Carbon::now();
        // Массив с датами, события в которых не были синхронизированы
        $dateArray = [];

        $current_date = $last_sync_date->copy();

        while ($current_date->lte($now)) {  // пока $current_date меньше или равен $now
            $dateArray[] = $current_date->copy();
            $current_date->addDay();

            // Защита от бесконечного цикла на случай ошибок
            if (count($dateArray) > 1000) {
                break;
            }
        }

        $last_arch_id = $sai[\'arch_id\'];
        $last_add_arch_id = $sai[\'add_arch_id\'];
        unset($sai);

        // Сохраняем последние записанные айдишники
        // Получаем максимальные значения
        $lastPKey = ArchEvents::orderByDesc(\'pkey\')->value(\'pkey\');
        $lastId = SkudAddArchEvent::orderByDesc(\'id\')->value(\'id\');


        // Выбираем последние записи о входе-выходе с момента последней сборки
        $archeDiff = ArchEvents::where(\'pkey\', ">", $last_arch_id)->pluck(\'add_code\')->toArray();

        // $archDateTimes = 
        // Получаем список юзеров, что отметились в СКУДЕ
        $users = StaffList::whereIn(\'passcard_blob\', $archeDiff)->pluck(\'id\')->toArray();
        // Список юзеров, которым за это время назначили кfстомные входы-выходы
        $users_2 = SkudAddArchEvent::where(\'id\', ">", $last_add_arch_id)->pluck(\'stafflist_id\')->toArray();

        // Собираем в кучку с уникальными айдишниками
        $UNIQ_USERS_ID = array_values(array_unique(array_merge($users, $users_2)));

        $startDate = Carbon::now();

        // Здесь происходит управление днями, в которые делается расчёт
        // Запускаем процессор для расчёта статистики и прочей нечисти
        // (new TimeSkudDailyCollector())->startDayProcessing($UNIQ_USERS_ID, $startTime, $endTime);
        // dd($dateArray, $UNIQ_USERS_ID);
        foreach ($dateArray AS $targDate){
            (new TimeSkudDailyCollector())->altDayProcessing($UNIQ_USERS_ID, $targDate);
        }


        // ADDITIONAL FEATURES:
        // 2 - Доп фича для тех, кто вышел за пределы офиса в рабочее время и не вернулся по окончанию рабочего дня
        $minutesToSyncSmokeUsers = [3, 13, 26, 39, 52];
        // запускается только в определенные минуты
        if (in_array( $startDate->minuteOfHour(), $minutesToSyncSmokeUsers)){
            // В ПРОДЕ ПЕРЕТАЩИТЬ СЮДА
        };
        $smoozers = SkudSyncEventsController::countUsersWhoLeaveJob($startDate, $UNIQ_USERS_ID);
        $UNIQ_USERS_ID = array_merge($UNIQ_USERS_ID, $smoozers);



        // В начале дня закрываем исполненные заявки
        if ($startDate->hourOfDay(0) && $startDate->minuteOfHour() == 1){
            // В ПРОДЕ ПЕРЕТАЩИТЬ СЮДА
        };
        SkudSyncEventsController::evaluatePastClaims();
        

        // dd($UNIQ_USERS_ID );
        if (!empty($UNIQ_USERS_ID)){
            WebSocketController::sendUpdateNotify($UNIQ_USERS_ID);
        };

        // Обновляем запись в инкременторе
        SkudArchIncrement::where(\'key_name\', \'skud_arch_daily\')
        ->update([
            \'arch_id\' => $lastPKey,
            \'add_arch_id\' => $lastId,
            \'updated_at\' => Carbon::now(),
        ]);

        echo "Time:";
        echo(microtime(true) - LARAVEL_START);
        echo " Users updated: " . count($UNIQ_USERS_ID) . " ";
        echo "Status: ";
        return "OK";
    }

