        [CommandMethod(&quot;BlkPreview&quot;)]
        static public void BlkPreview()
        {
            try
            {
                Document doc = Application.DocumentManager.MdiActiveDocument;
                Database db = doc.Database;
                Editor ed = doc.Editor;

                PromptStringOptions pso = new PromptStringOptions(
                    &quot;\\nEnter block name: &quot;);

                PromptResult pr = ed.GetString(pso);

                if (pr.Status != PromptStatus.OK)
                    return;

                using (Transaction Tx = db.TransactionManager.StartTransaction())
                {
                    BlockTable table = Tx.GetObject(
                        db.BlockTableId,
                        OpenMode.ForRead)
                            as BlockTable;
                    if (!table.Has(pr.StringResult) == true)
                    {
                        ed.WriteMessage(
                            &quot;\\nNo block with name &quot; + pr.StringResult);
                        return;
                    }

                    BlockTableRecord blk = Tx.GetObject(
                        table[pr.StringResult],
                        OpenMode.ForRead)
                            as BlockTableRecord;
                    if (blk.PreviewIcon == null)
                    {
                        acedCommand(
                            5005,
                            &quot;BLOCKICON&quot;,
                            5005,
                            pr.StringResult,
                            5000);
                    }
                    var prevka = blk.PreviewIcon.GetThumbnailImage(256, 256, ThumbCallBack, IntPtr.Zero);

                    prevka.Save(&quot;G:\\\\TMP\\\\&quot; + pr.StringResult + &quot;.bmp&quot;);

                    //blk.PreviewIcon.Save(
                    //    &quot;G:\\\\TMP\\\\&quot; + pr.StringResult + &quot;.bmp&quot;);

                    Tx.Commit();
                }
                
            } catch (System.Exception ex)
            {
                Console.WriteLine(ex.ToString());
            }
        }
