  [CommandMethod(&quot;UNCOOX&quot;)]
        public void Uncoox()
        {
            Document doc = Application.DocumentManager.MdiActiveDocument;
            Database db = doc.Database;
            Editor ed = doc.Editor;

            // Prompt the user for the scale factor
            PromptDoubleOptions promptOptions = new PromptDoubleOptions(&quot;\\nEnter the scale factor: &quot;);
            PromptDoubleResult promptResult = ed.GetDouble(promptOptions);

            if (promptResult.Status != PromptStatus.OK)
            {
                ed.WriteMessage(&quot;\\nInvalid input or user canceled.&quot;);
                return;
            }

            double scaleFactor = promptResult.Value;

            using (Transaction trans = db.TransactionManager.StartTransaction())
            {
                try
                {
                    // Select objects to include in the block
                    PromptSelectionResult selResult = ed.GetSelection();
                    if (selResult.Status != PromptStatus.OK)
                    {
                        ed.WriteMessage(&quot;\\nSelection failed. Exiting command.&quot;);
                        return;
                    }

                    ObjectIdCollection objIds = new ObjectIdCollection(selResult.Value.GetObjectIds());

                    // Create a new block definition
                    var rand = new Random();

                    BlockTableRecord blockDefRecord = new BlockTableRecord();
                    blockDefRecord.Name = &quot;NewBlock_&quot; + rand.Next(999, 99999).ToString();
                    trans.AddNewlyCreatedDBObject(blockDefRecord, true);

                    //BlockTableRecord bbtr = db.BlockTableId.GetObject(OpenMode.ForWrite, true).AppendEntity(blockDefRecord);
                    

                    // Add selected objects to the block definition
                    foreach (ObjectId objId in objIds)
                    {
                        Entity ent = trans.GetObject(objId, OpenMode.ForRead) as Entity;
                        blockDefRecord.AppendEntity(ent.Clone() as Entity);
                        trans.AddNewlyCreatedDBObject(ent.Clone() as Entity, true);
                    }

                    // Insert the block reference at 0,0,0
                    BlockReference blockRef = new BlockReference(Point3d.Origin, blockDefRecord.ObjectId);
                    blockRef.ScaleFactors = new Scale3d(100, 100, 100);

                    BlockTableRecord modelSpace = trans.GetObject(db.CurrentSpaceId, OpenMode.ForWrite) as BlockTableRecord;
                    modelSpace.AppendEntity(blockRef);
                    trans.AddNewlyCreatedDBObject(blockRef, true);

                    // Remove original objects
                    foreach (ObjectId objId in objIds)
                    {
                        Entity ent = trans.GetObject(objId, OpenMode.ForWrite) as Entity;
                        ent.Erase();
                    }

                    trans.Commit();
                }
                catch (System.Exception ex)
                {
                    ed.WriteMessage(&quot;\\nError: &quot; + ex.Message);
                    trans.Abort();
                }
                ed.Regen();
            }
        }
