#include&lt;iostream&gt;
#include&lt;glad/glad.h&gt;
#include&lt;GLFW/glfw3.h&gt;


int main()
{
	// Initalize FLFW
	glfwInit();

	// Tell GLFW what version of OpenGL we are using
	// In this case we are using OpenGL 3.3
	glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
	glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
	// Tell GLFW we are using the CORE profile
	// So that means we only have the modern functions
	glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);

	// Create a GLFWwindow object of 800 by 800 poxesl, naming it ...
	GLFWwindow* window = glfwCreateWindow(800, 800, &quot;MamaTubeGL&quot;, nullptr, nullptr);
	// Error check if the window fails to create
	if (window == NULL) 
	{
		std::cout &lt;&lt; &quot;Failed to create GLFW window&quot; &lt;&lt; std::endl;
		glfwTerminate();
		return -1;
	}
	// Context holds all objects of OpenGL
	// Introduce the window into the current context
	glfwMakeContextCurrent(window);

	// Load needed configuration of OpenGL
	// Load GLAD so it configures OpenGL
	gladLoadGL();

	// Specify the viewport of the OpenGL in the window
	// In this case thee viewport goes from x = 0, y = 0, to x = 800, y = 800
	glViewport(0, 0, 800, 900);

	// Specify the color of the background
	glClearColor(0.07f, 0.13f, 0.17f, 1.0f);
	// Clean the back buffer and assing the new color to it
	glClear(GL_COLOR_BUFFER_BIT);
	// Swap the back buffer with the front buffer
	glfwSwapBuffers(window);

	// Main While Loop
	while (!glfwWindowShouldClose(window))
	{
		// If we don&#039;t do this, the window gives the status &quot;not responding&quot;
		// Tabke care of all GLFW events
		glfwPollEvents();
	}

	// Delete window before ending the program
	glfwDestroyWindow(window);
	// Terminate GLFW before ending the program
	glfwTerminate();
	return 0;
}
```

