&lt;/span&gt;&lt;span class=&quot;&quot;&gt;&lt;span class=&quot;&quot;&gt;&lt;strong&gt;Example Code:&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;&quot;&gt;
&lt;/span&gt;&lt;span class=&quot;&quot;&gt;&lt;ul class=&quot;list-outside list-disc&quot;&gt;
&lt;li&gt;&lt;span class=&quot;&quot;&gt;
&lt;/span&gt;&lt;span class=&quot;&quot;  style=&#039;background: #f8f8f8;&#039;&gt;&lt;span class=&quot;&quot;&gt;JavaScript Code:&lt;/span&gt;&lt;/span&gt;
