using Microsoft.Office.Interop.Excel;
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Runtime.InteropServices;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading.Tasks;


namespace ConsoleExcelTest
{
    internal class ExcelDataExporter
    {
        public ExcelDataExporter() { }

        public bool demoFunc()
        {
            Microsoft.Office.Interop.Excel.Application xlApp = new Microsoft.Office.Interop.Excel.Application();

            if (xlApp == null)
            {
                Console.WriteLine(&quot;Excel is not properly installed!!&quot;);


                return false;
            } else
            {
                Console.WriteLine(&quot;OKAY&quot;);
                
            }

            object misValue = System.Reflection.Missing.Value;
            var xlWorkBook = xlApp.Workbooks.Add(misValue);

            var xlWorkSheet = (Microsoft.Office.Interop.Excel.Worksheet)xlWorkBook.Worksheets.get_Item(1);
            xlWorkSheet.Cells[1, 1] = &quot;ID&quot;;
            xlWorkSheet.Cells[1, 2] = &quot;Name&quot;;
            xlWorkSheet.Cells[1, 3] = &quot;Name&quot;;
            xlWorkSheet.Cells[1, 4] = &quot;Name&quot;;
            xlWorkSheet.Cells[1, 5] = &quot;Name&quot;;
            

            int maxRows = 100;
            for (int i = 0;i &lt; maxRows; i++)
            {
                int row = i + 2;
                xlWorkSheet.Cells[row, 1] = i.ToString();
                xlWorkSheet.Cells[row, 2] = i.ToString().GetHashCode();
                xlWorkSheet.Cells[row, 3] = (i * 2).ToString().GetHashCode();
                xlWorkSheet.Cells[row, 4] = (i * 9).ToString().GetHashCode();
                xlWorkSheet.Cells[row, 5] = (i * 3).ToString().GetHashCode();

                for (int j = 1; j &lt; 6; j++)
                {
                    this.SetCellAllBordersThin(ref xlWorkSheet, 1, j);
                    this.SetCellBackground(ref xlWorkSheet, 1, j, Color.LightSalmon);
                    this.SetCellTextFont(ref xlWorkSheet, 1, j, true);
                    this.SetCellWidth(ref xlWorkSheet, j, 10);
                    this.SetCellAlign(ref xlWorkSheet, 1, j, ContentAlignment.MiddleCenter);
                }
              
                Console.WriteLine(&quot;drawing row &quot; + row.ToString());
            }

            this.SetRowHeight(ref xlWorkSheet, 1, 3);

            for (int ex = 1; ex &lt; 6; ex++)
            {
                for (int i = 0; i &lt; maxRows; i++)
                {
                    int row = i + 2;

                    this.SetCellAllBordersThin(ref xlWorkSheet, row, ex);
                    if (ex == 1)
                    {
                        this.SetCellAlign(ref xlWorkSheet, row, ex, ContentAlignment.BottomLeft);

                    }

                }
                    Console.WriteLine(&quot;formatting col &quot; + ex.ToString());
            }




            xlWorkSheet = (Microsoft.Office.Interop.Excel.Worksheet)xlWorkBook.Worksheets.get_Item(2);
            xlWorkSheet.Cells[1, 1] = &quot;Sheet 2 content&quot;;

            xlWorkBook.SaveAs(&quot;your-file-name2.xls&quot;);

            xlApp.Quit();
            Marshal.ReleaseComObject(xlWorkSheet);
            Marshal.ReleaseComObject(xlWorkBook);

            Marshal.ReleaseComObject(xlApp);

            return true;
        }



        public void SetCellBordersCustom(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X,
            int top =  0, int bottom = 0, int left = 0, int right  = 0 
            )
        {
            var cell = workSheeet.Cells[Y, X];
            Console.WriteLine(&quot;Y row is &quot; + Y.ToString() + &quot; : X col is &quot; + X.ToString());
            Microsoft.Office.Interop.Excel.Borders border = cell.Borders;
            // Apply continuous line style to all borders
            // 
            if (left != 0)
                border[XlBordersIndex.xlEdgeLeft].LineStyle = left;
            if (top != 0)
                border[XlBordersIndex.xlEdgeTop].LineStyle = top;
            if (bottom != 0)
                border[XlBordersIndex.xlEdgeBottom].LineStyle = bottom;
            if (right != 0)
                border[XlBordersIndex.xlEdgeRight].LineStyle = right;
        }

        public void SetCellAllBordersThin(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X)
        {
            var cell = workSheeet.Cells[Y, X];
            Console.WriteLine(&quot;Y row is &quot; + Y.ToString() + &quot; : X col is &quot; + X.ToString());
            Microsoft.Office.Interop.Excel.Borders border = cell.Borders;
            // Apply continuous line style to all borders
            border[XlBordersIndex.xlEdgeLeft].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlContinuous;
            border[XlBordersIndex.xlEdgeTop].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlContinuous;
            border[XlBordersIndex.xlEdgeBottom].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlContinuous;
            border[XlBordersIndex.xlEdgeRight].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlContinuous;
        }

        public void SetCellAllBordersDash(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X)
        {
            var cell = workSheeet.Cells[Y, X];
            Console.WriteLine(&quot;Y row is &quot; + Y.ToString() + &quot; : X col is &quot; + X.ToString());
            Microsoft.Office.Interop.Excel.Borders border = cell.Borders;
            // Apply continuous line style to all borders
            border[XlBordersIndex.xlEdgeLeft].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlDash;
            border[XlBordersIndex.xlEdgeTop].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlDash;
            border[XlBordersIndex.xlEdgeBottom].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlDash;
            border[XlBordersIndex.xlEdgeRight].LineStyle = Microsoft.Office.Interop.Excel.XlLineStyle.xlDash;
        }


        public void SetRowHeight(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int height)
        {
            workSheeet.Cells[Y * 14.5, 1].RowHeight = height;
        }

        public void SetCellWidth(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int X, int width )
        {
            workSheeet.Cells[1, X].ColumnWidth = width;
        }


        public void SetCellBackground(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X, Color back = default)
        {
            var cell = workSheeet.Cells[Y, X];
            cell.Interior.Color = back;
        }

        public void SetCellAlign(ref Microsoft.Office.Interop.Excel.Worksheet workSheet, int Y, int X, 
            System.Drawing.ContentAlignment textAlign)
        {
            var cell = workSheet.Cells[Y, X];

            // Convert System.Drawing.ContentAlignment to Excel alignment enums
            Microsoft.Office.Interop.Excel.XlHAlign excelHorizontalAlign = Microsoft.Office.Interop.Excel.XlHAlign.xlHAlignCenter; // Default to Center
            Microsoft.Office.Interop.Excel.XlVAlign excelVerticalAlign = Microsoft.Office.Interop.Excel.XlVAlign.xlVAlignCenter; // Default to Center

            switch (textAlign)
            {
                case System.Drawing.ContentAlignment.TopLeft:
                case System.Drawing.ContentAlignment.MiddleLeft:
                case System.Drawing.ContentAlignment.BottomLeft:
                    excelHorizontalAlign = Microsoft.Office.Interop.Excel.XlHAlign.xlHAlignLeft;
                    break;
                case System.Drawing.ContentAlignment.TopCenter:
                case System.Drawing.ContentAlignment.MiddleCenter:
                case System.Drawing.ContentAlignment.BottomCenter:
                    excelHorizontalAlign = Microsoft.Office.Interop.Excel.XlHAlign.xlHAlignCenter;
                    break;
                case System.Drawing.ContentAlignment.TopRight:
                case System.Drawing.ContentAlignment.MiddleRight:
                case System.Drawing.ContentAlignment.BottomRight:
                    excelHorizontalAlign = Microsoft.Office.Interop.Excel.XlHAlign.xlHAlignRight;
                    break;
                    // Add more cases as needed for other horizontal alignments
            }

            switch (textAlign)
            {
                case System.Drawing.ContentAlignment.TopLeft:
                case System.Drawing.ContentAlignment.TopCenter:
                case System.Drawing.ContentAlignment.TopRight:
                    excelVerticalAlign = Microsoft.Office.Interop.Excel.XlVAlign.xlVAlignTop;
                    break;
                case System.Drawing.ContentAlignment.MiddleLeft:
                case System.Drawing.ContentAlignment.MiddleCenter:
                case System.Drawing.ContentAlignment.MiddleRight:
                    excelVerticalAlign = Microsoft.Office.Interop.Excel.XlVAlign.xlVAlignCenter;
                    break;
                case System.Drawing.ContentAlignment.BottomLeft:
                case System.Drawing.ContentAlignment.BottomCenter:
                case System.Drawing.ContentAlignment.BottomRight:
                    excelVerticalAlign = Microsoft.Office.Interop.Excel.XlVAlign.xlVAlignBottom;
                    break;
                    // Add more cases as needed for other vertical alignments
            }

            // Set the horizontal and vertical alignment for the cell
            cell.HorizontalAlignment = excelHorizontalAlign;
            cell.VerticalAlignment = excelVerticalAlign;
        }

        public void SetCellTextColor(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X, Color front = default)
        {
            var cell = workSheeet.Cells[Y, X];
            cell.Font.Color = front;
        }

        public void SetCellTextFont(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X,
            bool bold = false, bool italic = false, bool underline = false,
            bool strikethrough = false, int fontSize = 0, string fontName = &quot;&quot;)
        {
            var cell = workSheeet.Cells[Y, X];
            cell.Font.Bold = bold;
            cell.Font.Italic = italic;
            cell.Font.Underline = underline;
            cell.Font.Strikethrough = strikethrough;
            if (fontName != string.Empty)
            {
                cell.Font.FontName = fontName;
            }
            if (fontSize != 0)
            {
                cell.Font.Size = fontSize;
            }
        }

        public void SetCellBorderColors(ref Microsoft.Office.Interop.Excel.Worksheet workSheeet, int Y, int X,
            System.Drawing.Color top = default,
            System.Drawing.Color bottom = default,
            System.Drawing.Color left = default,
            System.Drawing.Color right = default
            )
        {
            var cell = workSheeet.Cells[Y, X];
            Microsoft.Office.Interop.Excel.Borders border = cell.Borders;

            // Set vertical borders to blue
            if (left != null)
            {
                border[XlBordersIndex.xlEdgeLeft].Color = left;
            }
            if (right != null)
            {
                border[XlBordersIndex.xlEdgeRight].Color = right;
            }

            // Set horizontal borders to gray
            if (top != null)
            {
                border[XlBordersIndex.xlEdgeTop].Color = top;
            }
            if (bottom != null)
            {
                border[XlBordersIndex.xlEdgeBottom].Color = bottom;
            }
        }

    }
}
