class Cooker
{
    constructor(applicationPrefix = &quot;&quot;, days = 30)
    {
        if (days &gt; 0 &amp;&amp; days &lt; 365){
            this.days = days;
        }
        this.prefix = null;

        if (applicationPrefix != &quot;&quot;){
            this.prefix = applicationPrefix;
        }

    }


    /**
     * setAppCookie - Set application cookie
     * @param {*} name 
     * @param {*} value 
     * @returns 
     */
    set(name, value)
    {
        if (this.prefix == null){
            console.error(&quot;set: Prefix is not sat!&quot;);
            return;
        }
        this.setCookie(this.prefix + name, value, this.days);
    }

    /**
     * getAppCookie - Get application cookie
     * @param {*} name 
     * @returns 
     */
    get(name)
    {
        if (this.prefix == null){
            console.error(&quot;Prefix is not sat!&quot;);
            return;
        }
        return this.getCookie(this.prefix + name);
    }

    /**
     * getAppCookieData - Get object from application cookie
     * @param {*} name 
     * @returns 
     */
    getData(name)
    {
        if (this.prefix == null){
            console.error(&quot;Prefix is not sat!&quot;);
            return;
        }
        return this.getObjectFromCookie(this.prefix + name);
    }

    /**
     * getAllAppCookies - Get all application cookies as object array
     * @returns 
     */
    getAll()
    {
        if (this.prefix != null){
            return this.getCookiesWithPrefix(this.prefix);
        } else {
            console.error(&quot;Prefix is not sat!&quot;);
        }
    }

    /**
     * getAllAppCookies - Get all objects of application from cookies
     */
    getAllObjects()
    {
        if (this.prefix == null){
            console.error(&quot;Prefix is not sat!&quot;);
            return;
        }
        let cookieresult = [];
        let array = this.getCookiesWithPrefix(this.prefix);
        for (let i = 0; i &lt; array.length; i++) {
            const element = array[i];
            let objer = element.value;
            cookieresult.push(JSON.parse(objer));
        }
        return cookieresult;
    }

    /**
     * eraseAppCookie - Erase application cookie
     * @param {*} name 
     * @returns 
     */
    erase(name)
    {
        if (this.prefix == null){
            console.error(&quot;Prefix is not sat!&quot;);
            return;
        }
        this.eraseCookie(this.prefix + name);
    }

    /**
     * eraseAllAppCookies
     */
    eraseAll()
    {
        if (this.prefix == null){
            console.error(&quot;Prefix is not sat!&quot;);
            return;
        }
        let array = this.getCookiesWithPrefix(this.prefix);
        for (let i = 0; i &lt; array.length; i++) {
            const element = array[i];
            this.eraseCookie(element.name);
        }
    }




    /**
     * Function to set a cookie
     *  */ 
    setCookie(name, value, days) {
        var expires = &quot;&quot;;
        if (days) {
            var date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = &quot;; expires=&quot; + date.toUTCString();
        }

            // Stringify the value if it&#039;s not a string or number
            if (typeof value !== &#039;string&#039; &amp;&amp; typeof value !== &#039;number&#039;) {
                value = JSON.stringify(value);
            }
        document.cookie = name + &quot;=&quot; + (value || &quot;&quot;) + expires + &quot;; path=/&quot;;
    }

    /**
     * Function to get a cookie
     * @param {*} name 
     * @returns 
     */
    getCookie(name) {
        var nameEQ = name + &quot;=&quot;;
        var ca = document.cookie.split(&#039;;&#039;);
        for (var i = 0; i &lt; ca.length; i++) {
            var c = ca[i];
            while (c.charAt(0) === &#039; &#039;) c = c.substring(1, c.length);
            if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
        }
        return null;
    }

    /**
     * Function to delete a cookie
     * @param {*} name 
     */
    eraseCookie(name) {
        document.cookie = name + &quot;=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;&quot;;
    }

    /**
     * Function to serialize an object to JSON and store it in a cookie
     * @param {*} name 
     * @param {*} object 
     * @param {*} days 
     */
    storeObjectInCookie(name, object, days) {
        this.setCookie(name, JSON.stringify(object), days);
    }

    /**
     * Function to retrieve a serialized object from a cookie and deserialize it
     * @param {*} name 
     * @returns 
     */
    getObjectFromCookie(name) {
        var cookieValue = this.getCookie(name);
        try {
            return cookieValue ? JSON.parse(cookieValue) : null;
        } catch (error) {
            return cookieValue.value;
        }
    }

    /**
     * Function to get all cookies with a specific prefix
     * @param {*} prefix 
     * @returns 
     */
    getCookiesWithPrefix(prefix) {
        var cookies = document.cookie.split(&#039;;&#039;);
        var filteredCookies = [];

        for (var i = 0; i &lt; cookies.length; i++) {
            var cookie = cookies[i].trim();
            if (cookie.indexOf(prefix) === 0) {
                var cookieParts = cookie.split(&#039;=&#039;);
                var cookieName = cookieParts.shift().trim();
                var cookieValue = decodeURIComponent(cookieParts.join(&#039;=&#039;));
                filteredCookies.push({ name: cookieName, value: cookieValue });
            }
        }

        return filteredCookies;
    }

}
