class ExtraMenu{
    constructor(container = &#039;offcanvas-extra-menu&#039;){
        this.url = &quot;/backside/company/&quot;;
        this.exMen = document.querySelector(&#039;#&#039; + container);
        const csrfToken = document.querySelector(&#039;meta[name=&quot;csrf-token&quot;]&#039;).getAttribute(&#039;content&#039;);
        if (this.exMen == null){
            console.error(&quot;Wrong id of menu container&quot;);
        }
        this.exMen.addEventListener(&quot;click&quot;, (e)=&gt;{
            if (e.target.closest(&#039;.ocn-com-trigger&#039;)){
                const tg = e.target.closest(&#039;.ocn-com-trigger&#039;).getAttribute(&#039;data-target&#039;);
                const response = fetch(this.url +  tg, {
                    method: &quot;POST&quot;,
                    headers: {
                        &#039;X-CSRF-TOKEN&#039;: csrfToken,
                        &#039;Content-Type&#039;: &#039;application/json&#039;
                    }
                });

                response.then(() =&gt; {
                        console.log(&#039;Company changed&#039;);
                        window.location.reload();
                });

            }
        } )
    }
}

let ExtraMenuInstance = new ExtraMenu();
```

