#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main()
{

    for (int u = 0; u &lt; 256; u++)
    {
        if (u &gt; 95 &amp;&amp; u &lt; 123)
            printf(&quot;%d\\t%c\\n&quot;, u, (char)u);
    }
    printf(&quot;\\n&quot;);
    printf(&quot;\\n&quot;);
    printf(&quot;\\n&quot;);

    char charr[21];
    for (int e = 0; e &lt; 20; e++)
    {
        charr[e] = (char)((rand() % (123 - 95)) + 95);
        //printf(&quot;%d&quot;, ((rand() % (123 - 95)) + 95));
    }
    printf(&quot;%s\\n&quot;, charr);

    return 0;
}
