('s_6702bb4312f872.82098882', 'Allocate and free memory in C', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'TQ0XVVCYEKYFG15B9T552AZBDK', NULL, NULL, NULL, NULL, '``` js
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    double *massiv = NULL;
    int cnt = 22;

    // Allocate memory for the array
    massiv = malloc(sizeof(*massiv) * cnt);
    if (massiv == NULL) {
        fprintf(stderr, &quot;Memory allocation failed\\n&quot;);
        return 1; // Exit if memory allocation fails
    }

    // Initialize the array
    for (int i = 0; i &lt; cnt; i++) {
        if (i == 0)
            massiv[i] = 1;
        else
            massiv[i] = massiv[i - 1] * 2;
    }

    // Resize the array
    cnt += 5;
    double *temp = realloc(massiv, sizeof(*massiv) * cnt);
    if (temp == NULL) {
        fprintf(stderr, &quot;Memory reallocation failed\\n&quot;);
        free(massiv); // Free the original memory before exiting
        return 1; // Exit if reallocation fails
    }
    massiv = temp;

    // Initialize new elements in the resized array
    for (int i = cnt - 5; i &lt; cnt; i++) {
        massiv[i] = 777;
    }

    // Print the elements of the array
    for (int i = 0; i &lt; cnt; i++) {
        printf(&quot;%f\\n&quot;, massiv[i]);
    }

    // Free the allocated memory
    free(massiv);
    
    return 0;
}
```', 1, 1, 1, 2, NULL, NULL, 0, 0, 0, 0, '2024-10-06 00:00:00', '2024-10-06 16:31:39', '2024-10-06 16:30:59'),
