('s_67043148f3dc62.34521997', 'C указатели на функции', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'TQ0XVVCYEKYFG15B9T552AZBDK', NULL, NULL, NULL, NULL, 'При вызове функции через указатель, мы вызываем ту функцию, на которую в данный момент указывает указатель. Указатель на функцию также позволяет передавать функцию в качестве входного параметра.

``` js
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;


typedef int (*TfuncAB) (int, int);

int Get5()
{
    return 5;
}


int Max(int a, int b)
{
    if (a &gt; b){
        return a;
    } else {
        return b;
    };
};

int Min(int a, int b)
{
    if (a &gt; b){
        return a;
    } else {
        return b;
    };
};


int GetOne(TfuncAB fn)
{
    if (fn != NULL)
        return fn(111, 33);
}


int main()
{
    float value;

    float *valPtr = &amp;value;
    *valPtr = 345;

    printf(&quot;%d \\n&quot;, Max(5,7) );
    
    // Pointer to function
    int (*func)();
    func = Get5;


    int (*pofunc) (int, int);
    pofunc = Max;
    printf(&quot;%d \\n&quot;, pofunc(55,7) );


    TfuncAB tfunc;
    tfunc = Max;
    printf(&quot;%d \\n&quot;, tfunc(55,987) );


    printf(&quot;%d \\n&quot;, GetOne(Max) );


    TfuncAB fnc[2];
    fnc[0] = Max;
    fnc[1] = Min;

    return 0;
}
```', 1, 1, 1, 2, NULL, NULL, 0, 0, 0, 0, '2024-10-07 00:00:00', '2024-10-07 19:22:32', '2024-10-07 19:06:49'),
