('s_671f91a67cfd92.41606737', 'an_bid_comments', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'A59GT3S93MKB77K9N1AQSF1AP1', NULL, NULL, NULL, NULL, 'CREATE TABLE auth_base.an_bid_comments(
