    p.y = 1120;
    p.SetTime(2564557);
    int t = p.GetTime();
    cout &lt;&lt; &quot;Hello wolf! ^ &quot; &lt;&lt; p.x &lt;&lt; &quot; @ &quot; &lt;&lt; t &lt;&lt; endl;
    return 0;
}
