``` js
#include &lt;iostream&gt;
#include &lt;cmath&gt;

using namespace std;

class Numic {
    int value = 0;
    int qrt = 0;
    int sqr = 0;
public:
    void SetValue(int val)
    {
        value = val;
        sqr = value * value;
        qrt = sqrt(value);
    };

    int GetRoot()
    {
        return qrt;
    };
    int GetSqr(){
        return sqr;
    }

    int GetValue(){
        return value;
    }
};


void Display(Numic num)
{
    int sqr = num.GetSqr();
    int qrt = num.GetRoot();
    int val = num.GetValue();
    cout &lt;&lt; &quot;Value is: &quot; &lt;&lt; val &lt;&lt; &quot;\\n&quot; &lt;&lt; endl;
    cout &lt;&lt; &quot;Root is: &quot; &lt;&lt; qrt &lt;&lt; &quot;\\n&quot; &lt;&lt; endl;
    cout &lt;&lt; &quot;Squeare is: &quot; &lt;&lt; sqr &lt;&lt; &quot;\\n&quot; &lt;&lt; endl;
};


int main()
{
    Numic num;
    num.SetValue(500);
    Display(num);

    return 0;
}
