('s_67458fd30b66f2.61399772', 'Преобразование числа в буквы и обратно', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'A59GT3S93MKB77K9N1AQSF1AP1', NULL, NULL, NULL, NULL, '```
    /**
     * Преобразование кода валюты в ASCII номера с лидирующей единицей (для сохранения нулей)
     */
    static function getCurrencyIntVal(string $charcode) : int
    {
        $asciiValues = [];
        // Convert each character to its ASCII value
        for ($i = 0; $i &lt; strlen($charcode); $i++) {
            $asciiValues[] = sprintf(&#039;%03d&#039;, ord($charcode[$i])); // Get ASCII value
        }
        // Concatenate ASCII values into a string
        $concatenatedString = &quot;1&quot; . implode(&#039;&#039;, $asciiValues);
        // Convert the concatenated string to an integer
        $integerValue = intval($concatenatedString);
        return $integerValue;
    }


    /**
     * Преобразование числа кода валюты с лидирующей единицей в буквенный код
     */
    static function getCurrencyCharVal(int $integerValue) : string
    {
        // Convert the integer back to a string
        $stringValue = (string)$integerValue;
    
        // Remove the leading &#039;1&#039;
        $stringValue = substr($stringValue, 1);
    
        // Initialize an empty array to hold the characters
        $chars = [];
    
        // Loop through the string in chunks of 3 characters
        for ($i = 0; $i &lt; strlen($stringValue); $i += 3) {
            // Get the next three characters
            $asciiChunk = substr($stringValue, $i, 3);
            
            // Convert the ASCII value back to a character
            if (strlen($asciiChunk) === 3) { // Ensure we have a full chunk
                $chars[] = chr((int)$asciiChunk); // Convert to character
            }
        }
    
        // Join the characters into a string
        return implode(&#039;&#039;, $chars);
    }
