('s_675745ed431b27.97230710', 'Проверка CURL на Laravel', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'A59GT3S93MKB77K9N1AQSF1AP1', NULL, NULL, NULL, NULL, '``` js
    Route::get(&#039;/getcontents&#039;, function () {
        $url = &#039;http://www.arstel.com/basemodels/show.php?name=001807_big_DIB-6000.jpg&amp;width=170&amp;height=149&amp;keepsize=1&#039;;

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); // Return the response as a string
        curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true); // Follow redirects if needed
        curl_setopt($ch, CURLOPT_USERAGENT, &#039;Mozilla/5.0&#039;); // Set a user agent if necessary

        $image_bin = curl_exec($ch);

        if ($image_bin === false) {
            echo &quot;cURL Error: &quot; . curl_error($ch);
        } else {
            $directory = storage_path(&quot;temp/BID_DOC_PHOTOS&quot;);

            // Check if the directory exists, if not, create it
            if (!is_dir($directory)) {
                mkdir($directory, 0755, true); // Create directory and set permissions
            }
            print_r($image_bin);
            // Successfully fetched the image binary
            echo &quot;Image fetched successfully.&quot;;
            file_put_contents($directory  . &quot;/gak.png&quot;, $image_bin);
            echo (&quot;READ -------------------------------------------------------- READ \\n&quot;);
            echo file_get_contents($directory  . &quot;/gak.png&quot;);

        }

        curl_close($ch);
    });
    // TEST ROUTES END
