('s_67eb9c68514ea4.02316043', 'REACT WORD HIGHLIGHT', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'TQ0XVVCYEKYFG15B9T552AZBDK', NULL, NULL, NULL, NULL, 'import React, { useState, useEffect } from &#039;react&#039;;


const TextHighlight = ({ text, searchWords }) =&gt; {
    if (searchWords === undefined || searchWords === null || searchWords.length === 0){
        return text;
    }

    const words = text.split(/\\s+/);
    const highlighted = words.map((word, index) =&gt; {
      const isMatch = searchWords.some(target =&gt; 
        word.toLowerCase().includes(target.toLowerCase())
      );
      
      if (isMatch) {
        // Выделение только совпадающего слова
        return (
          &lt;span key={index} className=&quot;highlight&quot;&gt;
            {word}
          &lt;/span&gt;
        );
      }
      return word;
    });
  
    return highlighted;
  };

  export default TextHighlight;', 1, 1, 1, 2, NULL, NULL, 0, 0, 0, 0, '2025-04-01 00:00:00', '2025-04-01 11:41:59', '2025-04-01 07:57:28'),
('s_67ebcfa64fdb45.42769606', 'Об игоре и переносах', '01KNHVWYBVJT0X6QN30HJ4VDVJ', NULL, 0, NULL, NULL, NULL, 'A59GT3S93MKB77K9N1AQSF1AP1', NULL, NULL, NULL, NULL, 'На прошлой неделе с 24 по 30 число звонили Игорю насчет обновления отдела продаж (внести изменения в базу данных). Только Игорь может вносить изменения в базу данных. Мы звонили вторник-среду 25-26, он сказал, что перенос будет в пятницу 28.
В пятницу Игорь перенес на понедельник. 
В понедельник Игорь оказался в пути, выяснилось что он в отпуске, и сказал, что будет готов внести изменения во вторник  во второй половине дня.

