// app/Console/Commands/IncrementVersion.php
public function handle()
{
    $type = $this-&gt;argument(&#039;type&#039;); // patch / minor / major
    $current = config(&#039;app.version&#039;);
    [$major, $minor, $patch] = explode(&#039;.&#039;, $current);

    match ($type) {
        &#039;major&#039; =&gt; ++$major,
        &#039;minor&#039; =&gt; ++$minor,
        &#039;patch&#039; =&gt; ++$patch,
    };

    $newVersion = &quot;$major.$minor.$patch&quot;;

    // Обновите .env или запишите в базу
    file_put_contents(base_path(&#039;.env&#039;), str_replace(
        &quot;APP_VERSION=$current&quot;, &quot;APP_VERSION=$newVersion&quot;, file_get_contents(base_path(&#039;.env&#039;))
    ));

    $this-&gt;info(&quot;Version updated from $current to $newVersion&quot;);
}
